    float gap = p.Z - map_z;
    if (!(gap < 0.7f)) return;
    float cx = 0.5f - (float)fmod((double)p.X, 1.0), cy = 0.5f - (float)fmod((double)p.Y, 1.0);
    float fx = 0, fy = 0, fz = 0;
    for (int i = 0; i < 9; ++i) {
        float tx = g_BlockNeighbourOffsets[i].X + cx, ty = g_BlockNeighbourOffsets[i].Y + cy;
        float m = (float)sqrt(tx * tx + ty * ty);
