    Case("fade2", 10.8f, 20.1f, 1.0f + 2.7f + 0.1f, -0.6f, 0.9f, 0.0f, false, 1);
    Case("edge", 10.5f, 20.5f, 1.0f + 2.625f + 0.6999f, 1.0f, 0.5f, 0.0f, false, 1);
